# Run Tests -- PowerShell wrapper for unit and deploy test projects.
# Auto-generated by datrix-codegen-dotnet. Do not edit manually.
#
# Usage:
#   ./tests/run-tests.ps1            # Run both unit and deploy tests
#   ./tests/run-tests.ps1 -Unit      # Run unit tests only
#   ./tests/run-tests.ps1 -Deploy    # Run deploy tests only

param(
    [switch]$Unit,
    [switch]$Deploy
)

$ErrorActionPreference = "Stop"

$runUnit = -not $Deploy -or $Unit
$runDeploy = -not $Unit -or $Deploy

if ($runUnit) {
    Write-Host "Running unit tests..." -ForegroundColor Cyan
    $unitExit = 0
    Push-Location ecommerce_user_service/tests/UserService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    Push-Location ecommerce_product_service/tests/ProductService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    Push-Location ecommerce_order_service/tests/OrderService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    Push-Location ecommerce_payment_service/tests/PaymentService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    Push-Location ecommerce_shipping_service/tests/ShippingService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    Push-Location ecommerce_notification_service/tests/NotificationService.Tests
    try {
        dotnet test
        if ($LASTEXITCODE -ne 0) { $unitExit = $LASTEXITCODE }
    } finally {
        Pop-Location
    }
    if ($unitExit -ne 0) { exit $unitExit }
}

if ($runDeploy) {
    Write-Host "Running deploy tests..." -ForegroundColor Cyan
    Write-Host "Starting compose stack (build + up, waiting for healthy)..." -ForegroundColor Cyan
    docker compose up -d --build --wait --wait-timeout 300
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
    $deployExit = 0
    try {
        # Resolve each reachable service's REAL host-published port.
        $hostPort = (docker compose port ecommerce-user-service 8006 2>$null) -replace '^.*:', ''
        if ($hostPort) { $env:USER_SERVICE_BASE_URL = "http://localhost:$hostPort" }
        $hostPort = (docker compose port ecommerce-product-service 8004 2>$null) -replace '^.*:', ''
        if ($hostPort) { $env:PRODUCT_SERVICE_BASE_URL = "http://localhost:$hostPort" }
        $hostPort = (docker compose port ecommerce-order-service 8002 2>$null) -replace '^.*:', ''
        if ($hostPort) { $env:ORDER_SERVICE_BASE_URL = "http://localhost:$hostPort" }
        $hostPort = (docker compose port ecommerce-payment-service 8003 2>$null) -replace '^.*:', ''
        if ($hostPort) { $env:PAYMENT_SERVICE_BASE_URL = "http://localhost:$hostPort" }
        $hostPort = (docker compose port ecommerce-shipping-service 8005 2>$null) -replace '^.*:', ''
        if ($hostPort) { $env:SHIPPING_SERVICE_BASE_URL = "http://localhost:$hostPort" }
        Push-Location tests/DeployTests
        try {
            dotnet test
            $deployExit = $LASTEXITCODE
        } finally {
            Pop-Location
        }
    } finally {
        Write-Host "Stopping compose stack..." -ForegroundColor Cyan
        docker compose down -v --remove-orphans
    }
    if ($deployExit -ne 0) { exit $deployExit }
}
